      if (miss.producer) bits.push('post says *' + (pf.producer || '—') + '*, masterlist says *' + (on.producer || '—') + '* _(producer)_');
      lines.push((i + 1) + '. ' + x.quDisplay + ' — ' + bits.join('; '));
    });
  }

  if (!res.notFound.length && !res.mismatch.length) {
    lines.push('');
    lines.push('✅ All clear — every QU matches the masterlist.');
  }

